90	    // immersive-ar はパススルー映像の上に描画するセッション。
91	    // optionalFeatures は非対応でもセッション開始に失敗せず、session.enabledFeatures で結果が分かる。
92	    const session = await navigator.xr.requestSession('immersive-ar', {
93	      requiredFeatures: REQUIRED_FEATURES.map((f) => f.id),
94	      optionalFeatures: OPTIONAL_FEATURES.map((f) => f.id),
95	      // GPU テクスチャとして深度を受け取る (three.js が遮蔽に使う)。形式はブラウザ任せ。
96	      depthSensing: { usagePreference: ['gpu-optimized'], dataFormatPreference: [] },
97	    });
98	    await this.renderer.xr.setSession(session);
99	    this.session = session;
100	    this.lastTime = 0;
101	    this.failed.clear();
102	    session.addEventListener('end', this.handleSessionEnd);
