128	  private readonly handleFrame = (timeMs: number, frame?: XRFrame): void => {
129	    const session = this.session;
130	    const refSpace = this.renderer.xr.getReferenceSpace();
131	    if (!frame || !session || !refSpace) return;
132	
133	    const time = timeMs / 1000;
134	    const dt = this.lastTime === 0 ? 1 / 72 : Math.min(time - this.lastTime, 0.05);
135	    this.lastTime = time;
136	
137	    const viewerPose = frame.getViewerPose(refSpace);
138	    if (viewerPose) {
139	      const { position, orientation } = viewerPose.transform;
140	      this.headPosition.set(position.x, position.y, position.z);
141	      this.headQuaternion.set(orientation.x, orientation.y, orientation.z, orientation.w);
142	    }
143	
144	    const ctx: FrameContext = {
145	      time,
146	      dt,
147	      frame,
148	      session,
149	      refSpace,
150	      headPosition: this.headPosition,
151	      headQuaternion: this.headQuaternion,
152	    };
153	    for (const feature of this.features) {
154	      if (this.failed.has(feature)) continue;
155	      try {
156	        feature.update?.(ctx);
157	      } catch (error) {
158	        this.reportFailure(feature, 'update', error);
159	      }
160	    }
161	    this.renderer.render(this.scene, this.camera);
162	  };
