83	  update(): void {
84	    for (const hold of new Set(this.held.values())) {
85	      const [first, second] = hold.hands;
86	      if (second && hold.twoHand) {
87	        if (!first.hand.tracked || !second.hand.tracked) continue;
88	        const start = hold.twoHand;
89	        const direction = _direction.copy(second.hand.grabPosition).sub(first.hand.grabPosition);
90	        const distance = Math.max(direction.length(), 0.02);
91	        direction.normalize();
92	        // 一緒に持っている物の大きさが違っても形が崩れないよう、倍率は全体で 1 つにする。
93	        const base = hold.parts[0].scale;
94	        const ratio = THREE.MathUtils.clamp(distance / start.distance, MIN_SCALE / base, MAX_SCALE / base);
95	        // 両手を結ぶ線の向きの変化を、そのまま物の回転にする。
96	        _delta.setFromUnitVectors(start.direction, direction);
97	        _middle.addVectors(first.hand.grabPosition, second.hand.grabPosition).multiplyScalar(0.5);
98	        for (const part of hold.parts) {
99	          part.object.quaternion.copy(_delta).multiply(part.quaternion);
100	          part.object.position.copy(part.position).applyQuaternion(_delta).multiplyScalar(ratio).add(_middle);
101	          part.object.scale.setScalar(part.scale * ratio);
102	        }
103	      } else {
104	        const hand = first.hand;
105	        if (!hand.tracked) continue;
106	        for (const part of hold.parts) {
107	          part.object.quaternion.copy(hand.grabQuaternion).multiply(part.quaternion);
108	          part.object.position.copy(part.position).applyQuaternion(hand.grabQuaternion).add(hand.grabPosition);
109	        }
110	      }
111	    }
112	  }
