114	  private tryHold(hand: HandState, button: HoldButton): boolean {
115	    if (!hand.tracked || this.held.has(hand)) return false;
116	    // 線の近くでも描き足せるよう、つまみを道具に譲る。握る / グリップでは持てる。
117	    if (button === 'select' && this.app.tools.active?.overridesHold) return false;
118	    let nearest: Holdable | null = null;
119	    let nearestDistance = HOLD_MARGIN;
120	    for (const holdable of this.holdables) {
121	      if (holdable.canHold && !holdable.canHold()) continue;
122	      const distance = holdable.distanceTo(hand.grabPosition);
123	      if (distance < nearestDistance) {
124	        nearest = holdable;
125	        nearestDistance = distance;
126	      }
127	    }
128	    if (!nearest) return false;
129	
130	    const other = this.held.get(this.app.input.other(hand));
131	    let hold: Hold;
132	    if (other?.parts.some((part) => part.object === nearest.object)) {
133	      // もう一方の手が持っている物なら、両手持ちにする。
134	      hold = other;
135	      hold.hands.push({ hand, button });
136	    } else {
137	      // もう一方の手が持っている物は、そちらに任せる。
138	      const objects = (nearest.group?.() ?? [nearest.object]).filter(
139	        (object) => !other?.parts.some((part) => part.object === object),
140	      );
141	      hold = {
142	        hands: [{ hand, button }],
143	        parts: objects.map((object) => ({
144	          object,
145	          position: new THREE.Vector3(),
146	          quaternion: new THREE.Quaternion(),
147	          scale: 1,
148	        })),
149	        twoHand: null,
150	      };
151	    }
152	    this.held.set(hand, hold);
153	    this.beginHold(hold);
154	    hand.pulse(0.5, 25);
155	    return true;
156	  }
157	
158	  private release(hand: HandState, button: HoldButton): void {
159	    const hold = this.held.get(hand);
160	    const index = hold?.hands.findIndex((holder) => holder.hand === hand && holder.button === button) ?? -1;
161	    if (!hold || index < 0) return;
162	    this.held.delete(hand);
163	    hold.hands.splice(index, 1);
164	    if (hold.hands.length > 0) this.beginHold(hold);
165	    hand.pulse(0.25, 20);
166	  }
167	
168	  /** 持ち手の数が変わったときに、その時点の位置関係を基準として覚え直す。 */
169	  private beginHold(hold: Hold): void {
170	    const [first, second] = hold.hands;
171	    if (second) {
172	      const direction = _direction.copy(second.hand.grabPosition).sub(first.hand.grabPosition);
173	      const distance = Math.max(direction.length(), 0.02);
174	      hold.twoHand = { direction: direction.clone().normalize(), distance };
175	      _middle.addVectors(first.hand.grabPosition, second.hand.grabPosition).multiplyScalar(0.5);
176	      for (const part of hold.parts) {
177	        part.position.copy(part.object.position).sub(_middle);
178	        part.quaternion.copy(part.object.quaternion);
179	        part.scale = part.object.scale.x;
180	      }
181	    } else {
182	      hold.twoHand = null;
183	      const hand = first.hand;
184	      _delta.copy(hand.grabQuaternion).invert();
185	      for (const part of hold.parts) {
186	        part.position.copy(part.object.position).sub(hand.grabPosition).applyQuaternion(_delta);
187	        part.quaternion.copy(_delta).multiply(part.object.quaternion);
188	        part.scale = part.object.scale.x;
189	      }
190	    }
191	  }
192	}
