3	/** メニューで切り替える「道具」。つまみ / トリガーで何が起きるかを決める。 */
4	export interface Tool {
5	  id: string;
6	  label: string;
7	  /** メニューに出す 1 行の操作説明 */
8	  hint: string;
9	  /** つまみ / トリガーを、近くの写真や線を持つこと (Holding) より優先する */
10	  overridesHold?: boolean;
11	  onSelectStart(hand: HandState): void;
12	  onSelectEnd?(hand: HandState): void;
13	}
14	
15	/** select を道具より先に横取りする処理。処理したら true を返す。 */
16	export type Interceptor = (hand: HandState) => boolean;
17	
18	/**
19	 * select (つまみ / トリガー) の行き先を決める。
20	 * 登録順に interceptor を試し (メニューを押す、近くの物をつかむ)、
21	 * 誰も処理しなければ選択中の道具に渡す。
22	 */
23	export class Tools {
24	  readonly list: Tool[] = [];
25	  active: Tool | null = null;
26	  onChange: (() => void) | null = null;
27	
28	  private readonly interceptors: Interceptor[] = [];
29	  /** selectstart を受けた道具。途中で道具を切り替えても selectend を同じ道具に返す。 */
30	  private readonly started = new Map<HandState, Tool>();
31	
32	  constructor(input: Input) {
33	    input.on('selectstart', (hand) => {
34	      // 手を握ると、親指が人差し指に触れてつまみと判定されることがある。握っている手のつまみは無視する。
35	      if (hand.isHand && hand.squeezing) return;
36	      if (this.interceptors.some((intercept) => intercept(hand))) return;
37	      const tool = this.active;
38	      if (!tool) return;
39	      this.started.set(hand, tool);
40	      tool.onSelectStart(hand);
41	    });
42	    input.on('selectend', (hand) => {
43	      const tool = this.started.get(hand);
44	      this.started.delete(hand);
45	      tool?.onSelectEnd?.(hand);
46	    });
47	  }
48	
49	  register(tool: Tool): void {
50	    this.list.push(tool);
51	    this.active ??= tool;
52	    this.onChange?.();
53	  }
54	
55	  addInterceptor(interceptor: Interceptor): void {
56	    this.interceptors.push(interceptor);
57	  }
58	
59	  setActive(tool: Tool): void {
60	    this.active = tool;
61	    this.onChange?.();
62	  }
63	}
