1	import * as THREE from 'three';
2	import type { App, Feature, FrameContext } from '../app';
3	import type { HandState } from '../input';
4	import { GROUP_ALL, GROUP_HAND, RAPIER, interactionGroups } from '../physics';
5	import type { SavedPose } from './persistence';
6	
7	export type ToyKind = 'ball' | 'block';
8	type GrabButton = 'select' | 'squeeze';
9	
10	interface Toy {
11	  kind: ToyKind;
12	  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.MeshStandardMaterial>;
13	  body: RAPIER.RigidBody;
14	  collider: RAPIER.Collider;
15	  /** 拡大率。両手でつかんで変える。 */
16	  scale: number;
17	  holders: HandState[];
18	  /** 片手で持っているときの、手から見た物の位置と向き */
19	  offsetPosition: THREE.Vector3;
20	  offsetQuaternion: THREE.Quaternion;
21	  /** 両手で持ち始めた瞬間の状態 */
22	  twoHand: {
23	    middle: THREE.Vector3;
24	    direction: THREE.Vector3;
25	    distance: number;
26	    scale: number;
27	    relativePosition: THREE.Vector3;
28	    quaternion: THREE.Quaternion;
29	  } | null;
30	  /** 手から離れたばかりで、まだ手の当たり判定と重なっているので、手とはぶつからないようにしている */
31	  passingHands: boolean;
32	  lastImpactTime: number;
33	}
34	
35	interface SavedToy {
36	  kind: ToyKind;
37	  color: number;
38	  pose: SavedPose;
39	}
40	
41	/** 球の半径 / ブロックの一辺の半分 (m) */
42	const BASE_SIZE = 0.05;
43	const MIN_SCALE = 0.4;
44	const MAX_SCALE = 6;
45	const MAX_TOYS = 40;
46	/** 物の表面からこの距離までなら、つかめる (m) */
47	const GRAB_MARGIN = 0.05;
48	/** これより遅い衝突では音を出さない (m/s) */
49	const MIN_IMPACT_SPEED = 0.3;
50	const MIN_IMPACT_INTERVAL = 0.08;
51	
52	const BALL_GEOMETRY = new THREE.SphereGeometry(BASE_SIZE, 32, 20);
53	const BLOCK_GEOMETRY = new THREE.BoxGeometry(BASE_SIZE * 2, BASE_SIZE * 2, BASE_SIZE * 2);
54	
55	const COLLIDE_WITH_ALL = interactionGroups(GROUP_ALL, GROUP_ALL);
56	const PASS_THROUGH_HANDS = interactionGroups(GROUP_ALL, GROUP_ALL & ~GROUP_HAND);
57	/** 手の当たり判定だけを探す問い合わせ */
58	const HANDS_ONLY = interactionGroups(GROUP_ALL, GROUP_HAND);
59	
60	const _a = new THREE.Vector3();
61	const _b = new THREE.Vector3();
62	const _delta = new THREE.Quaternion();
63	
64	/**
65	 * つかんで投げられるボールとブロック。現実の床・壁・机 (Room の当たり判定) で跳ね返る。
66	 * - 物の近くでつまむ・手全体で握る / グリップを握る: つかむ
67	 * - 何もない所でつまむ / トリガー: 手の中に新しく出す
68	 * - 両手で同じ物をつかむ: 手の間隔で拡大縮小、手の向きで回転
69	 */
70	export class Toys implements Feature {
71	  readonly name = 'toys';
72	  /** 物がぶつかったときの通知 (効果音用) */
73	  onImpact: ((position: THREE.Vector3, speed: number, kind: ToyKind) => void) | null = null;
74	
75	  private readonly toys: Toy[] = [];
76	  private readonly byCollider = new Map<number, Toy>();
77	  private readonly held = new Map<HandState, { toy: Toy; button: GrabButton }>();
78	  private time = 0;
79	
80	  constructor(private readonly app: App) {
81	    const { input, tools } = app;
82	    tools.addInterceptor((hand) => this.tryGrab(hand, 'select'));
83	    input.on('selectend', (hand) => this.release(hand, 'select'));
84	    input.on('squeezestart', (hand) => void this.tryGrab(hand, 'squeeze'));
85	    input.on('squeezeend', (hand) => this.release(hand, 'squeeze'));
86	
87	    tools.register({
88	      id: 'ball',
89	      label: 'ボール',
90	      hint: 'つまむ/トリガーで出し、離して投げる',
91	      onSelectStart: (hand) => this.spawnInHand('ball', hand),
92	    });
93	    tools.register({
94	      id: 'block',
95	      label: 'ブロック',
96	      hint: '出して積む。両手でつかむと拡大・回転',
97	      onSelectStart: (hand) => this.spawnInHand('block', hand),
98	    });
99	    app.onClear(() => this.clear());
100	    app.physics.onCollisionStart((c1, c2) => this.handleCollision(c1, c2));
101	    app.persistence.register<SavedToy[]>('toys', {
102	      save: () =>
103	        this.toys.map((toy) => ({
104	          kind: toy.kind,
105	          color: toy.mesh.material.color.getHex(),
106	          pose: app.persistence.poseOf(toy.mesh),
107	        })),
108	      restore: (saved) => {
109	        for (const { kind, color, pose } of saved) {
110	          if (this.toys.length >= MAX_TOYS) break;
111	          const mesh = createMesh(kind, new THREE.Color(color));
112	          app.persistence.place(mesh, pose);
113	          // 眠らせた状態で戻す。復元の時点では、床や机の当たり判定がまだ届いていないことがあり、
114	          // 動ける状態で置くと、そのまま下へ落ちていってしまう。何かが当たるか、つかめば動き出す。
115	          this.addToy(kind, mesh, true);
116	        }
117	      },
118	    });
119	  }
120	
121	  get count(): number {
122	    return this.toys.length;
123	  }
124	
125	  end(): void {
126	    this.clear();
127	  }
128	
129	  clear(): void {
130	    while (this.toys.length > 0) this.remove(this.toys[0]);
131	  }
132	
133	  update(ctx: FrameContext): void {
134	    this.time = ctx.time;
135	    for (let i = this.toys.length - 1; i >= 0; i--) {
136	      const toy = this.toys[i];
137	      if (toy.holders.length > 0) {
138	        this.followHands(toy);
139	      } else {
140	        const position = toy.body.translation();
141	        if (position.y < -10) {
142	          // 当たり判定の無い所から落ちていった物は片付ける。
143	          this.remove(toy);
144	          continue;
145	        }
146	        toy.mesh.position.set(position.x, position.y, position.z);
147	        const rotation = toy.body.rotation();
148	        toy.mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
149	        if (toy.passingHands && !this.touchesHands(toy)) this.setPassingHands(toy, false);
150	      }
151	    }
152	  }
153	
154	  /**
155	   * 離した瞬間の物は、まだ指の当たり判定に埋まっている。そのまま手とぶつかると、
156	   * めり込みを解消しようとして弾き飛ばされるので、手から抜けきるまでは手とぶつからないようにする。
157	   */
158	  private setPassingHands(toy: Toy, passing: boolean): void {
159	    toy.passingHands = passing;
160	    toy.collider.setCollisionGroups(passing ? PASS_THROUGH_HANDS : COLLIDE_WITH_ALL);
161	  }
162	
163	  private touchesHands(toy: Toy): boolean {
164	    let touching = false;
165	    this.app.physics.world.intersectionsWithShape(
166	      toy.collider.translation(),
167	      toy.collider.rotation(),
168	      toy.collider.shape,
169	      () => {
170	        touching = true;
171	        return false;
172	      },
173	      undefined,
174	      HANDS_ONLY,
175	    );
176	    return touching;
177	  }
178	
179	  private spawnInHand(kind: ToyKind, hand: HandState): void {
180	    if (!hand.tracked || this.held.has(hand)) return;
181	    if (this.toys.length >= MAX_TOYS) {
182	      const oldest = this.toys.find((toy) => toy.holders.length === 0);
183	      if (oldest) this.remove(oldest);
184	    }
185	    const mesh = createMesh(kind, new THREE.Color().setHSL(Math.random(), 0.75, 0.55));
186	    mesh.position.copy(hand.grabPosition);
187	    mesh.quaternion.copy(hand.grabQuaternion);
188	    this.grab(this.addToy(kind, mesh, false), hand, 'select');
189	  }
190	
191	  /** メッシュの位置・向き・大きさに合わせて、物理の剛体を作る。 */
192	  private addToy(kind: ToyKind, mesh: Toy['mesh'], sleeping: boolean): Toy {
193	    const world = this.app.physics.world;
194	    const scale = THREE.MathUtils.clamp(mesh.scale.x, MIN_SCALE, MAX_SCALE);
195	    mesh.scale.setScalar(scale);
196	    this.app.scene.add(mesh);
197	
198	    const body = world.createRigidBody(
199	      RAPIER.RigidBodyDesc.dynamic()
200	        .setTranslation(mesh.position.x, mesh.position.y, mesh.position.z)
201	        .setRotation(mesh.quaternion)
202	        // 投げた球が薄い壁をすり抜けないよう、連続衝突判定を使う。
203	        .setCcdEnabled(true)
204	        .setLinearDamping(0.05)
205	        .setAngularDamping(0.4)
206	        .setSleeping(sleeping),
207	    );
208	    const toy: Toy = {
209	      kind,
210	      mesh,
211	      body,
212	      collider: world.createCollider(colliderDesc(kind, scale), body),
213	      scale,
214	      holders: [],
215	      offsetPosition: new THREE.Vector3(),
216	      offsetQuaternion: new THREE.Quaternion(),
217	      twoHand: null,
218	      passingHands: false,
219	      lastImpactTime: 0,
220	    };
221	    this.byCollider.set(toy.collider.handle, toy);
222	    this.toys.push(toy);
223	    return toy;
224	  }
225	
226	  private tryGrab(hand: HandState, button: GrabButton): boolean {
227	    if (!hand.tracked || this.held.has(hand)) return false;
228	    let nearest: Toy | null = null;
229	    let nearestDistance = Infinity;
230	    for (const toy of this.toys) {
231	      // ブロックは角までの距離を見込んで広めに取る。
232	      const reach = BASE_SIZE * toy.scale * (toy.kind === 'ball' ? 1 : 1.5) + GRAB_MARGIN;
233	      const distance = toy.mesh.position.distanceTo(hand.grabPosition) - reach;
234	      if (distance < 0 && distance < nearestDistance) {
235	        nearest = toy;
236	        nearestDistance = distance;
237	      }
238	    }
239	    if (!nearest) return false;
240	    this.grab(nearest, hand, button);
241	    return true;
242	  }
243	
244	  private grab(toy: Toy, hand: HandState, button: GrabButton): void {
245	    if (toy.holders.length >= 2) return;
246	    if (toy.holders.length === 0) {
247	      // 持っている間は手に追従させるだけなので、物理の力を受けない kinematic にする。
248	      toy.body.setBodyType(RAPIER.RigidBodyType.KinematicPositionBased, true);
249	    }
250	    toy.holders.push(hand);
251	    this.held.set(hand, { toy, button });
252	    this.beginHold(toy);
253	    hand.pulse(0.5, 25);
254	  }
255	
256	  private release(hand: HandState, button: GrabButton): void {
257	    const holding = this.held.get(hand);
258	    if (!holding || holding.button !== button) return;
259	    this.held.delete(hand);
260	    const toy = holding.toy;
261	    toy.holders.splice(toy.holders.indexOf(hand), 1);
262	    if (toy.twoHand) this.rebuildCollider(toy);
263	
264	    if (toy.holders.length > 0) {
265	      this.beginHold(toy);
266	      return;
267	    }
268	    // 手を離した瞬間の手の速度を、そのまま物の初速にする。
269	    toy.body.setBodyType(RAPIER.RigidBodyType.Dynamic, true);
270	    toy.body.setTranslation(toy.mesh.position, true);
271	    toy.body.setRotation(toy.mesh.quaternion, true);
272	    toy.body.setLinvel(hand.velocity, true);
273	    toy.body.setAngvel({ x: 0, y: 0, z: 0 }, true);
274	    this.setPassingHands(toy, true);
275	    hand.pulse(0.25, 20);
276	  }
277	
278	  /** 持ち手の数が変わったときに、その時点の位置関係を基準として覚え直す。 */
279	  private beginHold(toy: Toy): void {
280	    const [first, second] = toy.holders;
281	    if (second) {
282	      const direction = _a.copy(second.grabPosition).sub(first.grabPosition);
283	      const distance = Math.max(direction.length(), 0.02);
284	      const middle = new THREE.Vector3().addVectors(first.grabPosition, second.grabPosition).multiplyScalar(0.5);
285	      toy.twoHand = {
286	        middle,
287	        direction: direction.clone().normalize(),
288	        distance,
289	        scale: toy.scale,
290	        relativePosition: toy.mesh.position.clone().sub(middle),
291	        quaternion: toy.mesh.quaternion.clone(),
292	      };
293	    } else {
294	      toy.twoHand = null;
295	      _delta.copy(first.grabQuaternion).invert();
296	      toy.offsetPosition.copy(toy.mesh.position).sub(first.grabPosition).applyQuaternion(_delta);
297	      toy.offsetQuaternion.copy(_delta).multiply(toy.mesh.quaternion);
298	    }
299	  }
300	
301	  private followHands(toy: Toy): void {
302	    const [first, second] = toy.holders;
303	    const mesh = toy.mesh;
304	    if (second && toy.twoHand) {
305	      const start = toy.twoHand;
306	      const direction = _a.copy(second.grabPosition).sub(first.grabPosition);
307	      const distance = Math.max(direction.length(), 0.02);
308	      direction.normalize();
309	      toy.scale = THREE.MathUtils.clamp((start.scale * distance) / start.distance, MIN_SCALE, MAX_SCALE);
310	      // 両手を結ぶ線の向きの変化を、そのまま物の回転にする。
311	      _delta.setFromUnitVectors(start.direction, direction);
312	      mesh.quaternion.copy(_delta).multiply(start.quaternion);
313	      mesh.position
314	        .copy(start.relativePosition)
315	        .applyQuaternion(_delta)
316	        .multiplyScalar(toy.scale / start.scale)
317	        .add(_b.addVectors(first.grabPosition, second.grabPosition).multiplyScalar(0.5));
318	      mesh.scale.setScalar(toy.scale);
319	    } else {
320	      mesh.quaternion.copy(first.grabQuaternion).multiply(toy.offsetQuaternion);
321	      mesh.position.copy(toy.offsetPosition).applyQuaternion(first.grabQuaternion).add(first.grabPosition);
322	    }
323	    toy.body.setNextKinematicTranslation(mesh.position);
324	    toy.body.setNextKinematicRotation(mesh.quaternion);
325	  }
326	
327	  /** Rapier のコライダーは後から拡大できないので、大きさが変わったら作り直す。 */
328	  private rebuildCollider(toy: Toy): void {
329	    const world = this.app.physics.world;
330	    this.byCollider.delete(toy.collider.handle);
331	    world.removeCollider(toy.collider, false);
332	    toy.collider = world.createCollider(colliderDesc(toy.kind, toy.scale), toy.body);
333	    this.setPassingHands(toy, toy.passingHands);
334	    this.byCollider.set(toy.collider.handle, toy);
335	  }
336	
337	  private remove(toy: Toy): void {
338	    for (const hand of toy.holders) this.held.delete(hand);
339	    this.byCollider.delete(toy.collider.handle);
340	    // 剛体を消すと、付いているコライダーも一緒に消える。
341	    this.app.physics.world.removeRigidBody(toy.body);
342	    this.app.scene.remove(toy.mesh);
343	    toy.mesh.material.dispose();
344	    this.toys.splice(this.toys.indexOf(toy), 1);
345	  }
346	
347	  private handleCollision(collider1: number, collider2: number): void {
348	    for (const toy of [this.byCollider.get(collider1), this.byCollider.get(collider2)]) {
349	      if (!toy || toy.holders.length > 0) continue;
350	      if (this.time - toy.lastImpactTime < MIN_IMPACT_INTERVAL) continue;
351	      const velocity = toy.body.linvel();
352	      const speed = Math.hypot(velocity.x, velocity.y, velocity.z);
353	      if (speed < MIN_IMPACT_SPEED) continue;
354	      toy.lastImpactTime = this.time;
355	      const position = toy.body.translation();
356	      this.onImpact?.(_a.set(position.x, position.y, position.z), speed, toy.kind);
357	      // 2 つの物どうしの衝突でも、音は 1 回でよい。
358	      return;
359	    }
360	  }
361	}
362	
363	function createMesh(kind: ToyKind, color: THREE.Color): Toy['mesh'] {
364	  const material = new THREE.MeshStandardMaterial({ color, roughness: kind === 'ball' ? 0.35 : 0.7 });
365	  const mesh = new THREE.Mesh(kind === 'ball' ? BALL_GEOMETRY : BLOCK_GEOMETRY, material);
366	  mesh.castShadow = true;
367	  return mesh;
368	}
369	
370	function colliderDesc(kind: ToyKind, scale: number): RAPIER.ColliderDesc {
371	  const size = BASE_SIZE * scale;
372	  const desc = kind === 'ball' ? RAPIER.ColliderDesc.ball(size) : RAPIER.ColliderDesc.cuboid(size, size, size);
373	  return desc
374	    .setDensity(kind === 'ball' ? 300 : 500)
375	    .setRestitution(kind === 'ball' ? 0.75 : 0.15)
376	    .setFriction(kind === 'ball' ? 0.5 : 0.9)
377	    .setActiveEvents(RAPIER.ActiveEvents.COLLISION_EVENTS);
378	}
