28	const GROUPS: Group[] = ['tool', 'toggle', 'action'];
29	
30	/** 左手からメニューまでの高さ (m) */
31	const HAND_OFFSET = 0.13;
32	/**
33	 * 左手のひらの向きの上向き成分が SHOW を超えたらメニューを出し、HIDE を下回ったら隠す。
34	 * 境目で点滅しないよう、出す条件と隠す条件に差をつけている。
35	 */
36	const PALM_UP_SHOW = Math.cos(THREE.MathUtils.degToRad(50));
37	const PALM_UP_HIDE = Math.cos(THREE.MathUtils.degToRad(65));
38	/** 指先がパネルの手前この距離より離れると、次の押下を受け付ける (m) */
39	const POKE_ARM_DISTANCE = 0.02;
40	/** レイでメニューを押せる最大距離 (m) */
41	const RAY_REACH = 2;
42	
43	const _forward = new THREE.Vector3();
44	
45	/**
46	 * 左手の上に浮かぶメニュー。左手のひらを上に向けている間だけ現れる。
47	 * 反対の手の指先で直接押すか、レイを当ててつまむ / トリガーで押す。
48	 * 左手が見つからないときは、最後にあった場所 (最初は正面) に留まる。
49	 */
50	export class Menu implements Feature {
51	  readonly name = 'menu';
52	  /** ボタンが押されたときの通知 (効果音など) */
53	  onPress: ((position: THREE.Vector3) => void) | null = null;
54	
55	  private readonly items: MenuItem[] = [];
56	  private panel: CanvasPanel | null = null;
57	  /** ボタンの構成が変わったので、パネルを作り直す必要がある */
58	  private layoutDirty = true;
59	  /** 見た目が変わったので、描き直す必要がある */
60	  private dirty = true;
61	  private toolCount = 0;
62	  private time = 0;
63	  private placedInFront = false;
64	  private palmUp = false;
65	  private readonly pokeArmed = new Map<HandState, boolean>();
66	
67	  constructor(private readonly app: App) {
68	    app.tools.onChange = () => {
69	      // 道具の選択が変わっただけなら、描き直すだけでよい。
70	      if (app.tools.list.length !== this.toolCount) this.syncTools();
71	      this.dirty = true;
72	    };
73	    app.tools.addInterceptor((hand) => this.tryRayPress(hand));
74	    this.syncTools();
75	  }
76	
77	  addToggle(label: string, get: () => boolean, set: (value: boolean) => void): void {
78	    this.addItem('toggle', label, get, () => set(!get()));
79	  }
80	
81	  addAction(label: string, run: () => void): void {
82	    this.addItem('action', label, () => false, run);
83	  }
84	
85	  start(): void {
86	    this.placedInFront = false;
87	    this.palmUp = false;
88	    this.pokeArmed.clear();
89	    this.layoutDirty = true;
90	  }
91	
92	  end(): void {
93	    if (this.panel) this.panel.mesh.visible = false;
94	  }
95	
96	  update(ctx: FrameContext): void {
97	    if (this.layoutDirty) this.rebuild();
98	    const panel = this.panel;
99	    if (!panel) return;
100	    this.time = ctx.time;
101	    this.updatePlacement(panel, ctx);
102	    if (panel.mesh.visible) this.updatePoke(panel);
103	    if (this.items.some((item) => item.flashUntil > 0 && item.flashUntil <= ctx.time)) {
104	      for (const item of this.items) if (item.flashUntil <= ctx.time) item.flashUntil = 0;
105	      this.dirty = true;
106	    }
107	    if (this.dirty) this.draw(panel);
108	  }
109	
110	  /** 道具の一覧は Tools が持っているので、道具が増えたらボタンを作り直す。 */
111	  private syncTools(): void {
112	    const tools = this.app.tools;
113	    const others = this.items.filter((item) => item.group !== 'tool');
114	    this.items.length = 0;
115	    for (const tool of tools.list) {
116	      this.addItem(
117	        'tool',
118	        tool.label,
119	        () => tools.active === tool,
120	        () => tools.setActive(tool),
121	      );
122	    }
123	    this.items.push(...others);
124	    this.toolCount = tools.list.length;
125	  }
126	
127	  private addItem(group: Group, label: string, isActive: () => boolean, press: () => void): void {
128	    this.items.push({ group, label, isActive, press, x: 0, y: 0, width: 0, height: 0, flashUntil: 0 });
129	    // ここでは作り直さない。フレーム処理の途中でパネルを差し替えると、古い方に描いてしまう。
130	    this.layoutDirty = true;
131	  }
132	
133	  /** ボタンの数からレイアウトを決め、パネルを作り直す。 */
134	  private rebuild(): void {
135	    this.layoutDirty = false;
136	    const widthPx = PANEL_WIDTH * PIXELS_PER_METER;
137	    const buttonWidth = (widthPx - MARGIN * (COLUMNS + 1)) / COLUMNS;
138	    let y = HEADER_HEIGHT;
139	    for (const group of GROUPS) {
140	      const items = this.items.filter((item) => item.group === group);
141	      if (items.length === 0) continue;
142	      y += SECTION_HEIGHT;
143	      items.forEach((item, i) => {
144	        item.x = MARGIN + (i % COLUMNS) * (buttonWidth + MARGIN);
145	        item.y = y + Math.floor(i / COLUMNS) * (BUTTON_HEIGHT + MARGIN);
146	        item.width = buttonWidth;
147	        item.height = BUTTON_HEIGHT;
148	      });
149	      y += Math.ceil(items.length / COLUMNS) * (BUTTON_HEIGHT + MARGIN);
150	    }
151	
152	    const old = this.panel;
153	    const panel = new CanvasPanel(PANEL_WIDTH, y / PIXELS_PER_METER, PIXELS_PER_METER);
154	    // メニューは他の仮想物体に埋もれないよう、最後に深度を無視して描く。
155	    panel.mesh.renderOrder = 100;
156	    panel.mesh.material.depthTest = false;
157	    if (old) {
158	      panel.mesh.position.copy(old.mesh.position);
159	      panel.mesh.quaternion.copy(old.mesh.quaternion);
160	      panel.mesh.visible = old.mesh.visible;
161	      this.app.scene.remove(old.mesh);
162	      old.texture.dispose();
163	      old.mesh.geometry.dispose();
164	      old.mesh.material.dispose();
165	    }
166	    this.app.scene.add(panel.mesh);
167	    this.panel = panel;
168	    this.dirty = true;
169	  }
170	
171	  private updatePlacement(panel: CanvasPanel, ctx: FrameContext): void {
172	    const mesh = panel.mesh;
173	    const left = this.app.input.left;
174	    if (left.tracked) {
175	      mesh.position.copy(left.grabPosition);
176	      mesh.position.y += HAND_OFFSET + panel.height / 2;
177	      this.palmUp = left.palmNormal.y > (this.palmUp ? PALM_UP_HIDE : PALM_UP_SHOW);
178	      // 左手で物をつかんでいる間は邪魔なので隠す。
179	      mesh.visible = this.palmUp && !left.selecting && !left.squeezing;
180	      this.placedInFront = true;
181	    } else if (!this.placedInFront) {
182	      _forward.set(0, 0, -1).applyQuaternion(ctx.headQuaternion).setY(0).normalize();
183	      mesh.position.copy(ctx.headPosition).addScaledVector(_forward, 0.45);
184	      mesh.position.y -= 0.25;
185	      mesh.visible = true;
186	      this.placedInFront = true;
187	    } else {
188	      mesh.visible = true;
189	    }
190	    mesh.lookAt(ctx.headPosition);
191	    mesh.updateMatrixWorld();
192	  }
193	
194	  /** メニューを持っている手 (左手が見えていれば左手) では押せない。 */
195	  private canPress(hand: HandState): boolean {
196	    const left = this.app.input.left;
197	    return hand.tracked && !(left.tracked && hand === left);
198	  }
199	
200	  /** 指先がパネルの表から裏へ抜けた瞬間に、その位置のボタンを押す。 */
201	  private updatePoke(panel: CanvasPanel): void {
202	    for (const hand of this.app.input.hands) {
203	      if (!this.canPress(hand)) {
204	        this.pokeArmed.set(hand, false);
205	        continue;
206	      }
207	      const point = panel.project(hand.tipPosition);
208	      if (!point || point.distance > POKE_ARM_DISTANCE) {
209	        this.pokeArmed.set(hand, true);
210	      } else if (point.distance < 0.005 && point.distance > -0.04 && this.pokeArmed.get(hand)) {
211	        this.pokeArmed.set(hand, false);
212	        this.pressAt(point.x, point.y, hand);
213	      }
214	    }
215	  }
216	
217	  private tryRayPress(hand: HandState): boolean {
218	    const panel = this.panel;
219	    if (!panel || !panel.mesh.visible || !this.canPress(hand)) return false;
220	    const point = panel.raycast(hand.rayOrigin, hand.rayDirection);
221	    if (!point || point.distance > RAY_REACH) return false;
222	    this.pressAt(point.x, point.y, hand);
223	    // ボタンの隙間でも、メニュー越しに道具が発動しないよう入力は消費する。
224	    return true;
225	  }
226	
227	  private pressAt(x: number, y: number, hand: HandState): void {
228	    const item = this.items.find(
229	      (it) => x >= it.x && x <= it.x + it.width && y >= it.y && y <= it.y + it.height,
230	    );
231	    if (!item) return;
232	    item.flashUntil = this.time + 0.15;
233	    hand.pulse(0.6, 30);
234	    this.onPress?.(hand.tipPosition);
235	    try {
236	      item.press();
237	    } catch (error) {
238	      // ボタンの処理の失敗で、メニューごと止まらないようにする。
239	      console.error(`[menu] 「${item.label}」の処理に失敗しました`, error);
240	    }
241	    this.dirty = true;
242	  }
243	
244	  private draw(panel: CanvasPanel): void {
245	    this.dirty = false;
246	    const g = panel.context;
247	    const { width, height } = panel.canvas;
248	    g.clearRect(0, 0, width, height);
249	    g.fillStyle = 'rgba(16, 20, 28, 0.88)';
250	    g.beginPath();
251	    g.roundRect(0, 0, width, height, 24);
252	    g.fill();
253	
254	    g.textBaseline = 'middle';
255	    g.textAlign = 'left';
256	    g.fillStyle = '#ffffff';
257	    g.font = 'bold 30px system-ui, sans-serif';
258	    g.fillText('MR プレイルーム', MARGIN + 6, 30);
259	    g.fillStyle = '#a9b4c8';
260	    g.font = '20px system-ui, sans-serif';
261	    g.fillText(this.app.tools.active?.hint ?? '', MARGIN + 6, 70, width - MARGIN * 2 - 12);
262	
263	    let lastGroup: Group | null = null;
264	    for (const item of GROUPS.flatMap((group) => this.items.filter((it) => it.group === group))) {
265	      if (item.group !== lastGroup) {
266	        lastGroup = item.group;
267	        g.textAlign = 'left';
268	        g.fillStyle = '#8a94a8';
269	        g.font = '20px system-ui, sans-serif';
270	        g.fillText(GROUP_TITLES[item.group], MARGIN + 6, item.y - SECTION_HEIGHT / 2 + 4);
271	      }
272	      const active = item.isActive();
273	      g.fillStyle = item.flashUntil > 0 ? '#ffffff' : active ? '#4f8cff' : '#2a3142';
274	      g.beginPath();
275	      g.roundRect(item.x, item.y, item.width, item.height, 14);
276	      g.fill();
277	      g.fillStyle = item.flashUntil > 0 ? '#10141c' : '#ffffff';
278	      g.textAlign = 'center';
279	      g.font = 'bold 24px system-ui, sans-serif';
280	      g.fillText(item.label, item.x + item.width / 2, item.y + item.height / 2 + 1, item.width - 12);
281	    }
282	    panel.markDirty();
283	  }
284	}
