1	import * as THREE from 'three';
2	import type { Feature, FrameContext } from './app';
3	
4	export type Handedness = 'left' | 'right';
5	export type InputEvent = 'selectstart' | 'selectend' | 'squeezestart' | 'squeezeend';
6	type Listener = (hand: HandState) => void;
7	
8	/** 速度の計算に使う、直近の位置の記録期間 (秒) */
9	const VELOCITY_WINDOW = 0.1;
10	/**
11	 * 素手で「握っている」とみなす、指の伸び具合 (付け根から先端の直線距離 / 指の長さ。まっすぐなら 1)。
12	 * 人差し指から小指までの 4 本すべてが START を下回ったら握り始め、どれかが END を超えたら離したとみなす。
13	 * つまむときは人差し指があまり曲がらないので、4 本とも見ることで、つまみと握りを区別する。
14	 */
15	const GRASP_START = 0.62;
16	const GRASP_END = 0.78;
17	const GRASP_FINGERS = ['index-finger', 'middle-finger', 'ring-finger', 'pinky-finger'] as const;
18	
19	const _a = new THREE.Vector3();
20	const _b = new THREE.Vector3();
21	const _c = new THREE.Vector3();
22	const _d = new THREE.Vector3();
23	
24	/**
25	 * 片手ぶんの入力状態。素手 (ハンドトラッキング) とコントローラーの違いを吸収する。
26	 * 座標はすべて local-floor 参照空間 (= ワールド座標)。
27	 */
28	export class HandState {
29	  source: XRInputSource | null = null;
30	  /** このフレームで姿勢が取れたか */
31	  tracked = false;
32	  /** 素手なら true、コントローラーなら false */
33	  isHand = false;
34	  /** 素手: つまんでいる / コントローラー: トリガーを引いている */
35	  selecting = false;
36	  /** 素手: 手全体で握っている / コントローラー: グリップボタンを握っている */
37	  squeezing = false;
38	  /** 素手のとき、人差し指から小指のうち、いちばん伸びている指の伸び具合 (まっすぐなら 1) */
39	  fingerExtension = 1;
40	
41	  /** 指し示すレイ (targetRaySpace) */
42	  readonly rayOrigin = new THREE.Vector3();
43	  readonly rayDirection = new THREE.Vector3(0, 0, -1);
44	  readonly rayQuaternion = new THREE.Quaternion();
45	  /** 物をつかむ位置。素手: 親指と人差し指の先の中点 / コントローラー: gripSpace */
46	  readonly grabPosition = new THREE.Vector3();
47	  /** つかんだ物の向きの基準。素手: 手首 / コントローラー: gripSpace */
48	  readonly grabQuaternion = new THREE.Quaternion();
49	  /** ボタンを押す・線を描く先端。素手: 人差し指の先 / コントローラー: レイの原点 */
50	  readonly tipPosition = new THREE.Vector3();
51	  /** 手のひらが向いている方向 (手のひらから外へ出る向き) */
52	  readonly palmNormal = new THREE.Vector3(0, -1, 0);
53	  /** grabPosition の速度 (m/s)。投げるときに使う。 */
54	  readonly velocity = new THREE.Vector3();
55	
56	  private readonly history: { time: number; position: THREE.Vector3 }[] = [];
57	
58	  constructor(readonly handedness: Handedness) {}
59	
60	  /** コントローラーを振動させる。素手や非対応の場合は何もしない。 */
61	  pulse(intensity: number, durationMs: number): void {
62	    const actuator = this.source?.gamepad?.hapticActuators?.[0] as
63	      | { pulse?: (value: number, duration: number) => Promise<boolean> }
64	      | undefined;
65	    void actuator?.pulse?.(intensity, durationMs)?.catch(() => {});
66	  }
67	
68	  /** @internal */
69	  updatePose(ctx: FrameContext): void {
70	    const { frame, refSpace } = ctx;
71	    const source = this.source;
72	    this.tracked = false;
73	    if (!source) return;
74	
75	    const rayPose = frame.getPose(source.targetRaySpace, refSpace);
76	    if (!rayPose) return;
77	    copyPosition(this.rayOrigin, rayPose.transform.position);
78	    copyQuaternion(this.rayQuaternion, rayPose.transform.orientation);
79	    this.rayDirection.set(0, 0, -1).applyQuaternion(this.rayQuaternion);
80	
81	    this.isHand = Boolean(source.hand);
82	    if (source.hand) {
83	      // XRHand は関節名 → XRJointSpace の Map。関節ごとに姿勢と半径が取れる。
84	      const indexTip = getJointPose(frame, source.hand, 'index-finger-tip', refSpace);
85	      const thumbTip = getJointPose(frame, source.hand, 'thumb-tip', refSpace);
86	      const wrist = getJointPose(frame, source.hand, 'wrist', refSpace);
87	      if (!indexTip || !thumbTip || !wrist) return;
88	      copyPosition(this.tipPosition, indexTip.transform.position);
89	      copyPosition(this.grabPosition, thumbTip.transform.position).add(this.tipPosition).multiplyScalar(0.5);
90	      copyQuaternion(this.grabQuaternion, wrist.transform.orientation);
91	      // 手の関節の空間は、-Y が手のひらから外へ出る向きと決められている。
92	      this.palmNormal.set(0, -1, 0).applyQuaternion(this.grabQuaternion);
93	      this.updateFingerExtension(frame, source.hand, refSpace);
94	    } else {
95	      const gripPose = source.gripSpace ? frame.getPose(source.gripSpace, refSpace) : null;
96	      const transform = (gripPose ?? rayPose).transform;
97	      copyPosition(this.grabPosition, transform.position);
98	      copyQuaternion(this.grabQuaternion, transform.orientation);
99	      this.tipPosition.copy(this.rayOrigin);
100	      // gripSpace は X 軸が手のひらに垂直。握ったとき、左手のひらは +X、右手のひらは -X を向く。
101	      this.palmNormal.set(this.handedness === 'left' ? 1 : -1, 0, 0).applyQuaternion(this.grabQuaternion);
102	    }
103	    this.tracked = true;
104	    this.updateVelocity(ctx.time);
105	  }
106	
107	  /** @internal */
108	  reset(): void {
109	    this.source = null;
110	    this.tracked = false;
111	    this.selecting = false;
112	    this.squeezing = false;
113	    this.fingerExtension = 1;
114	    this.history.length = 0;
115	    this.velocity.set(0, 0, 0);
116	  }
117	
118	  /** 関節が 1 つでも取れなければ、前の値を保つ。 */
119	  private updateFingerExtension(frame: XRFrame, hand: XRHand, refSpace: XRReferenceSpace): void {
120	    let extension = 0;
121	    for (const finger of GRASP_FINGERS) {
122	      const proximal = getJointPose(frame, hand, `${finger}-phalanx-proximal`, refSpace);
123	      const intermediate = getJointPose(frame, hand, `${finger}-phalanx-intermediate`, refSpace);
124	      const distal = getJointPose(frame, hand, `${finger}-phalanx-distal`, refSpace);
125	      const tip = getJointPose(frame, hand, `${finger}-tip`, refSpace);
126	      if (!proximal || !intermediate || !distal || !tip) return;
127	      const base = copyPosition(_a, proximal.transform.position);
128	      const middle = copyPosition(_b, intermediate.transform.position);
129	      const far = copyPosition(_c, distal.transform.position);
130	      const end = copyPosition(_d, tip.transform.position);
131	      const length = base.distanceTo(middle) + middle.distanceTo(far) + far.distanceTo(end);
132	      if (length < 1e-4) return;
133	      extension = Math.max(extension, base.distanceTo(end) / length);
134	    }
135	    this.fingerExtension = extension;
136	  }
137	
138	  private updateVelocity(time: number): void {
139	    const history = this.history;
140	    history.push({ time, position: this.grabPosition.clone() });
141	    while (history.length > 2 && time - history[0].time > VELOCITY_WINDOW) history.shift();
142	    const oldest = history[0];
143	    const elapsed = time - oldest.time;
144	    if (elapsed > 1e-4) {
145	      this.velocity.copy(this.grabPosition).sub(oldest.position).divideScalar(elapsed);
146	    }
147	  }
148	}
149	
150	/**
151	 * XRSession の inputSources とイベントを、左右の HandState にまとめる。
152	 * three.js の getController() を使わず XRInputSource を直接読んでいるのは、
153	 * WebXR の入力 API がどういう形をしているかをコード上で追えるようにするため。
154	 */
155	export class Input implements Feature {
156	  readonly name = 'input';
157	  readonly left = new HandState('left');
158	  readonly right = new HandState('right');
159	  readonly hands: readonly HandState[] = [this.left, this.right];
160	
161	  private readonly listeners: Record<InputEvent, Listener[]> = {
162	    selectstart: [],
163	    selectend: [],
164	    squeezestart: [],
165	    squeezeend: [],
166	  };
167	  private session: XRSession | null = null;
168	
169	  on(event: InputEvent, listener: Listener): void {
170	    this.listeners[event].push(listener);
171	  }
172	
173	  /** もう一方の手 */
174	  other(hand: HandState): HandState {
175	    return hand === this.left ? this.right : this.left;
176	  }
177	
178	  start(session: XRSession): void {
179	    this.session = session;
180	    session.addEventListener('selectstart', this.handleSelectStart);
181	    session.addEventListener('selectend', this.handleSelectEnd);
182	    session.addEventListener('squeezestart', this.handleSqueezeStart);
183	    session.addEventListener('squeezeend', this.handleSqueezeEnd);
184	  }
185	
186	  end(): void {
187	    const session = this.session;
188	    if (session) {
189	      session.removeEventListener('selectstart', this.handleSelectStart);
190	      session.removeEventListener('selectend', this.handleSelectEnd);
191	      session.removeEventListener('squeezestart', this.handleSqueezeStart);
192	      session.removeEventListener('squeezeend', this.handleSqueezeEnd);
193	    }
194	    this.session = null;
195	    for (const hand of this.hands) hand.reset();
196	  }
197	
198	  update(ctx: FrameContext): void {
199	    for (const hand of this.hands) {
200	      // 素手とコントローラーを持ち替えると、同じ handedness の別の XRInputSource に入れ替わる。
201	      let current: XRInputSource | null = null;
202	      for (const source of ctx.session.inputSources) {
203	        if (source.handedness === hand.handedness) current = source;
204	      }
205	      if (current !== hand.source) {
206	        // 入れ替わりで selectend が届かないことがあるので、押しっぱなしを残さない。
207	        if (hand.selecting) this.setSelecting(hand, false);
208	        if (hand.squeezing) this.setSqueezing(hand, false);
209	        hand.reset();
210	        hand.source = current;
211	      }
212	      hand.updatePose(ctx);
213	      // 素手には squeeze のイベントがないので、手全体で握る動きを指の曲がり具合から読んで、同じ通知にする。
