import type { App, FrameContext } from '../app';
import type { Audio } from '../features/audio';
import type { HitTest } from '../features/hitTest';
import type { Portal } from '../features/portal';
import type { Room } from '../features/room';
import type { Toys } from '../features/toys';
import type { HandState, InputEvent } from '../input';
import type { GrabInterceptor, ItemEvents, Items } from '../items';
import type { Interceptor } from '../tools';

/** 操作の分類。メニューの並び順と、ideas.md の分類 (D / C / M) に対応する。 */
export type InteractionCategory = 'delete' | 'duplicate' | 'menu';

/** 操作の実装から使える、ほかの機能 */
export interface InteractionServices {
  app: App;
  audio: Audio;
  room: Room;
  hitTest: HitTest;
  portal: Portal;
  toys: Toys;
}

/**
 * 操作の実装に渡すもの。
 * 入力や物の通知は、必ずここの on... / add... で受け取る。有効な間 (メニューでオンにしていて、MR 中) だけ呼ばれる。
 * app.input.on などに直接登録すると、オフにしても止まらないので使わない。
 */
export interface InteractionContext extends InteractionServices {
  readonly items: Items;
  /** つまみ / 握るの開始・終了 */
  onInput(event: InputEvent, listener: (hand: HandState) => void): void;
  /** 物を持った・離した・消した・複製した */
  onItems<K extends keyof ItemEvents>(event: K, listener: (event: ItemEvents[K]) => void): void;
  /** 近くの物を持とうとしたときに、持つ代わりに別のことをする。処理したら true */
  addGrabInterceptor(interceptor: GrabInterceptor): void;
  /**
   * つまみ / トリガーを、メニュー・物をつかむ・道具より先に横取りする。処理したら true。
   * 何もない所でつまんだときにも呼ばれるので、関係ない入力では false を返すこと。
   */
  addSelectInterceptor(interceptor: Interceptor): void;
}

/**
 * 持っている物を削除・複製する、ひとつの操作方法 (ideas.md の 1 案)。
 * `src/interactions/strategies/` に 1 ファイル 1 案で置き、InteractionFactory を default export すると、
 * 自動で読み込まれ、メニューの「持った物の操作 (試作)」にオン / オフのボタンが出る。
 */
export interface ItemInteraction {
  /** ideas.md の ID。例: 'D1' */
  readonly id: string;
  /** メニューのボタンに出す短い名前 (全角 6 文字程度まで)。ボタンには `${id} ${label}` と出る。 */
  readonly label: string;
  readonly category: InteractionCategory;
  /** 有効になったとき (オンにしたとき、またはオンのまま MR を始めたとき) */
  enable?(): void;
  /** 無効になったとき (オフにしたとき、または MR を終えたとき)。出している物や途中の状態を片付ける。 */
  disable?(): void;
  /** 有効な間、毎フレーム呼ばれる。物の削除・複製は ctx.items.remove / duplicate を通す。 */
  update?(frame: FrameContext): void;
}

export type InteractionFactory = (ctx: InteractionContext) => ItemInteraction;

import * as THREE from 'three';
import type { Item, Items } from '../items';

/** メニュー系の操作 (M1 ～ M3) が並べる、持っている物への操作 */
export interface ItemAction {
  id: 'delete' | 'duplicate';
  label: string;
  /** targets: 対象の物 (ふつうは items.heldBy(hand))。結果の物 (複製なら複製、削除なら空) を返す。 */
  run(items: Items, targets: readonly Item[]): Item[];
}

/** メニューから複製したときに、複製を元からずらす距離 (m) */
const DUPLICATE_OFFSET = 0.12;
const _position = new THREE.Vector3();

export const DELETE_ACTION: ItemAction = {
  id: 'delete',
  label: '消す',
  run(items, targets) {
    for (const item of targets) items.remove(item);
    return [];
  },
};

/** 複製を元の少し上に置く。持っている物でも、複製は持たれていない状態で現れる。 */
export const DUPLICATE_ACTION: ItemAction = {
  id: 'duplicate',
  label: '複製',
  run(items, targets) {
    const copies: Item[] = [];
    for (const item of targets) {
      const copy = items.duplicate(item);
      if (!copy) continue;
      _position.copy(copy.object.position);
      _position.y += DUPLICATE_OFFSET;
      copy.setPose(_position, copy.object.quaternion);
      copies.push(copy);
    }
    return copies;
  },
};

export const ITEM_ACTIONS: readonly ItemAction[] = [DELETE_ACTION, DUPLICATE_ACTION];

import type { Feature, FrameContext } from '../app';
import type { HandState, InputEvent } from '../input';
import type { GrabInterceptor, ItemEvents } from '../items';
import type { Interceptor } from '../tools';
import type {
  InteractionCategory,
  InteractionContext,
  InteractionFactory,
  InteractionServices,
  ItemInteraction,
} from './types';

/** strategies/ 以下の各ファイル。_ で始まるファイルは読み込まない (下書き用)。 */
const MODULES = import.meta.glob<{ default: InteractionFactory }>('./strategies/[!_]*.ts', { eager: true });

/** オンにしている操作の ID を、次回も覚えておくための localStorage のキー */
const STORAGE_KEY = 'mr-playroom:item-interactions';
const CATEGORY_ORDER: InteractionCategory[] = ['delete', 'duplicate', 'menu'];

interface Entry {
  interaction: ItemInteraction;
  /** メニューでオンにしている */
  enabled: boolean;
  /** enable を呼んでから disable を呼ぶまで (オン、かつ MR 中) */
  active: boolean;
  /** update か通知の処理で例外を出したので、MR を始め直すまで止めている */
  failed: boolean;
  input: Map<InputEvent, ((hand: HandState) => void)[]>;
  selectInterceptors: Interceptor[];
}

/**
 * 持っている物への操作 (削除・複製・メニュー) の試作を、メニューから 1 つずつオン / オフできるようにする。
 * 同時にいくつオンにしてもよいが、同じ動きを使う案どうしは取り合うことがある。
 */
export class ItemInteractions implements Feature {
  readonly name = 'itemInteractions';
  private readonly entries: Entry[] = [];
  private running = false;

  constructor(services: InteractionServices) {
    const { app } = services;
    const saved = loadEnabled();
    const factories = Object.entries(MODULES)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([path, module]) => ({ path, factory: module.default }));

    for (const { path, factory } of factories) {
      const entry: Entry = {
        interaction: null as unknown as ItemInteraction,
        enabled: false,
        active: false,
        failed: false,
        input: new Map(),
        selectInterceptors: [],
      };
      const live = (): boolean => entry.active && !entry.failed;
      const guard = <A extends unknown[], R>(fn: (...args: A) => R, fallback: R) => (...args: A): R => {
        if (!live()) return fallback;
        try {
          return fn(...args);
        } catch (error) {
          this.fail(entry, error);
          return fallback;
        }
      };
      const ctx: InteractionContext = {
        ...services,
        items: app.items,
        onInput: (event, listener) => {
          const list = entry.input.get(event) ?? [];
          list.push(listener);
          entry.input.set(event, list);
        },
        onItems: <K extends keyof ItemEvents>(event: K, listener: (payload: ItemEvents[K]) => void) => {
          app.items.on(event, guard(listener, undefined));
        },
        addGrabInterceptor: (interceptor: GrabInterceptor) => {
          app.items.addGrabInterceptor(guard(interceptor, false));
        },
        addSelectInterceptor: (interceptor) => entry.selectInterceptors.push(interceptor),
      };
      try {
        entry.interaction = factory(ctx);
      } catch (error) {
        console.error(`[itemInteractions] ${path} を読み込めませんでした`, error);
        continue;
      }
      entry.enabled = saved.has(entry.interaction.id);
      this.entries.push(entry);

      // 入力は、登録した順に 1 つずつ有効な操作へ配る。
      for (const event of ['selectstart', 'selectend', 'squeezestart', 'squeezeend'] as const) {
        app.input.on(event, (hand) => {
          for (const listener of entry.input.get(event) ?? []) guard(listener, undefined)(hand);
        });
      }
    }
    this.entries.sort(
      (a, b) =>
        CATEGORY_ORDER.indexOf(a.interaction.category) - CATEGORY_ORDER.indexOf(b.interaction.category) ||
        a.interaction.id.localeCompare(b.interaction.id),
    );

    // メニュー・物をつかむ・道具より先に試す。
    app.tools.addInterceptor(
      (hand) =>
        this.entries.some(
          (entry) =>
            entry.active &&
            !entry.failed &&
            entry.selectInterceptors.some((interceptor) => {
              try {
                return interceptor(hand);
              } catch (error) {
                this.fail(entry, error);
                return false;
              }
            }),
        ),
      { first: true },
    );

    for (const entry of this.entries) {
      const { id, label } = entry.interaction;
      app.menu.addToggle(
        `${id} ${label}`,
        () => entry.enabled,
        (value) => this.setEnabled(entry, value),
        'experiment',
      );
    }
  }

  /** オンにしている操作の ID */
  get enabledIds(): string[] {
    return this.entries.filter((entry) => entry.enabled).map((entry) => entry.interaction.id);
  }

  start(): void {
    this.running = true;
    for (const entry of this.entries) {
      entry.failed = false;
      if (entry.enabled) this.activate(entry);
    }
  }

  end(): void {
    this.running = false;
    for (const entry of this.entries) this.deactivate(entry);
  }

  update(frame: FrameContext): void {
    for (const entry of this.entries) {
      if (!entry.active || entry.failed) continue;
      try {
        entry.interaction.update?.(frame);
      } catch (error) {
        this.fail(entry, error);
      }
    }
  }

  private setEnabled(entry: Entry, enabled: boolean): void {
    entry.enabled = enabled;
    if (enabled && this.running) this.activate(entry);
    if (!enabled) this.deactivate(entry);
    saveEnabled(this.enabledIds);
  }

  private activate(entry: Entry): void {
    if (entry.active) return;
    entry.active = true;
    try {
      entry.interaction.enable?.();
    } catch (error) {
      this.fail(entry, error);
    }
  }

  private deactivate(entry: Entry): void {
    if (!entry.active) return;
    entry.active = false;
    try {
      entry.interaction.disable?.();
    } catch (error) {
      console.error(`[itemInteractions] ${entry.interaction.id} の片付けに失敗しました`, error);
    }
  }

  /** 1 つの操作の失敗で、ほかの操作やアプリ全体を止めない。 */
  private fail(entry: Entry, error: unknown): void {
    if (entry.failed) return;
    entry.failed = true;
    console.error(`[itemInteractions] ${entry.interaction.id} が失敗したため、MR を始め直すまで止めます`, error);
    this.deactivate(entry);
    // 止めた操作は、オンのままにしておく (次の MR で再び試す)。
  }
}

function loadEnabled(): Set<string> {
  try {
    const value: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
    return new Set(Array.isArray(value) ? value.filter((id): id is string => typeof id === 'string') : []);
  } catch {
    return new Set();
  }
}

function saveEnabled(ids: string[]): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(ids));
  } catch {
    // 保存できなくても、このセッション中の切り替えは効く。
  }
}

