1	import * as THREE from 'three';
2	import type { FrameContext } from '../../app';
3	import type { HandState } from '../../input';
4	import type { Item, ItemKind } from '../../items';
5	import type { InteractionFactory } from '../types';
6	
7	// D1 両手で縮めて消す。拡大縮小そのものは Holding / Toys が行い、ここでは
8	// 「最小の大きさを超えて、さらに潰そうとしている量」だけを見て、十分に潰したら消す。
9	
10	/** 物の種類ごとの最小の大きさ。holding.ts (写真・線) と toys.ts (ボール・ブロック) の MIN_SCALE に合わせる。 */
11	const MIN_SCALE: Record<ItemKind, number> = { photo: 0.25, stroke: 0.25, ball: 0.4, block: 0.4 };
12	/** 最小の大きさに達したとみなすのをやめる余裕 (最小の何倍まで戻ったら、達していない状態に戻すか)。振動が連続しないための余裕 */
13	const REACH_RELEASE = 1.05;
14	/** この量 (最小の大きさに対する、さらに潰した割合) を超えて潰すと、すぐ消える */
15	const CRUSH_DELETE = 0.35;
16	/** この量を超えて潰した状態を HOLD_SECONDS 保っても消える。手の距離が細かく揺れても消せるようにするため */
17	const CRUSH_HOLD = 0.1;
18	const HOLD_SECONDS = 0.8;
19	/** 潰している間の予告の色 */
20	const WARN_COLOR = 0xff4040;
21	/** 予告の振動の間隔 (秒) */
22	const WARN_PULSE_INTERVAL = 0.12;
23	
24	/**
25	 * 両手で持ち始めたときの手の距離と大きさから、いまの手の距離で、
26	 * 最小の大きさを超えてさらに潰そうとしている量を返す (0 なら潰していない、1 なら大きさ 0 相当)。
27	 * 拡大縮小は距離の比に比例するので、最小で止められる前の「本来の大きさ」を求めて比べる。
28	 */
29	export function crushAmount(startDistance: number, distance: number, startScale: number, minScale: number): number {
30	  if (startDistance <= 0 || minScale <= 0) return 0;
31	  const virtualScale = (startScale * distance) / startDistance;
32	  return Math.max(0, 1 - virtualScale / minScale);
33	}
34	
35	/** 最小の大きさに達しているか (本来の大きさが最小以下)。released は、いったん達したあとで戻ったか見るための余裕つき */
36	export function reachedMin(startDistance: number, distance: number, startScale: number, minScale: number, released = false): boolean {
37	  const virtualScale = (startScale * distance) / startDistance;
38	  return virtualScale <= minScale * (released ? REACH_RELEASE : 1);
39	}
40	
41	interface Crush {
42	  a: HandState;
43	  b: HandState;
44	  startDistance: number;
45	  startScale: number;
46	  reached: boolean;
47	  /** CRUSH_HOLD を超えて潰している時間 */
48	  held: number;
49	  pulseTimer: number;
50	  warning: THREE.Mesh | null;
51	}
52	
53	const _box = new THREE.Box3();
54	const _sphere = new THREE.Sphere();
55	
56	const create: InteractionFactory = (ctx) => {
57	  const crushes = new Map<Item, Crush>();
58	
59	  const clearWarning = (crush: Crush): void => {
60	    if (!crush.warning) return;
61	    crush.warning.removeFromParent();
62	    (crush.warning.material as THREE.Material).dispose();
63	    crush.warning.geometry.dispose();
64	    crush.warning = null;
65	  };
66	
67	  const forget = (item: Item): void => {
68	    const crush = crushes.get(item);
69	    if (!crush) return;
70	    clearWarning(crush);
71	    crushes.delete(item);
72	  };
73	
74	  // 物が消えた・持ち方が変わったときに、途中の状態を捨てる。
75	  ctx.onItems('removing', ({ item }) => forget(item));
76	  ctx.onItems('release', ({ items }) => items.forEach(forget));
77	
78	  const showWarning = (item: Item, crush: Crush, progress: number, time: number): void => {
79	    if (!crush.warning) {
80	      const material = new THREE.MeshBasicMaterial({ color: WARN_COLOR, transparent: true, depthWrite: false });
81	      crush.warning = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), material);
82	      ctx.app.scene.add(crush.warning);
83	    }
84	    _box.setFromObject(item.object).getBoundingSphere(_sphere);
85	    const shake = 1 + 0.08 * Math.sin(time * 60) * progress;
86	    crush.warning.position.copy(_sphere.center);
87	    crush.warning.scale.setScalar(Math.max(_sphere.radius, 0.01) * 1.1 * shake);
88	    (crush.warning.material as THREE.MeshBasicMaterial).opacity = 0.15 + 0.5 * progress;
89	  };
90	
91	  const step = (item: Item, frame: FrameContext): void => {
92	    const holders = ctx.items.holdersOf(item);
93	    if (holders.length !== 2) return forget(item);
94	    const [a, b] = holders;
95	    let crush = crushes.get(item);
96	    if (crush && (crush.a !== a || crush.b !== b)) {
97	      forget(item);
98	      crush = undefined;
99	    }
100	    const distance = Math.max(a.grabPosition.distanceTo(b.grabPosition), 0.02);
101	    // 両手で持った (grab 通知) 時点の距離と大きさを覚える。Holding / Toys も同じ時点を基準にしている。
102	    if (!crush) {
103	      crush = {
104	        a,
105	        b,
106	        startDistance: distance,
107	        startScale: item.object.scale.x,
108	        reached: false,
109	        held: 0,
110	        pulseTimer: 0,
111	        warning: null,
112	      };
113	      crushes.set(item, crush);
114	    }
115	    const min = MIN_SCALE[item.kind];
116	    const amount = crushAmount(crush.startDistance, distance, crush.startScale, min);
117	
118	    if (!crush.reached && reachedMin(crush.startDistance, distance, crush.startScale, min)) {
119	      crush.reached = true;
120	      a.pulse(0.6, 60);
121	      b.pulse(0.6, 60);
122	    } else if (crush.reached && !reachedMin(crush.startDistance, distance, crush.startScale, min, true)) {
123	      crush.reached = false;
124	    }
125	
126	    crush.held = amount >= CRUSH_HOLD ? crush.held + frame.dt : 0;
127	    const progress = Math.min(1, Math.max(amount / CRUSH_DELETE, crush.held / HOLD_SECONDS));
128	
129	    if (progress >= 1) {
130	      const position = item.object.position.clone();
131	      ctx.items.remove(item);
132	      ctx.audio.chime(position);
133	      a.pulse(1, 120);
134	      b.pulse(1, 120);
135	      return;
136	    }
137	    if (amount > 0) {
138	      showWarning(item, crush, progress, frame.time);
139	      crush.pulseTimer -= frame.dt;
140	      if (crush.pulseTimer <= 0) {
141	        crush.pulseTimer = WARN_PULSE_INTERVAL;
142	        a.pulse(0.2 + 0.4 * progress, 40);
143	        b.pulse(0.2 + 0.4 * progress, 40);
144	      }
145	    } else {
146	      // 手を開いて戻したら、予告をやめる。
147	      clearWarning(crush);
148	    }
149	  };
150	
151	  return {
152	    id: 'D1',
153	    label: '縮めて消す',
154	    category: 'delete',
155	    disable() {
156	      for (const crush of crushes.values()) clearWarning(crush);
157	      crushes.clear();
158	    },
159	    update(frame) {
160	      for (const item of [...ctx.items.all]) step(item, frame);
161	      for (const item of [...crushes.keys()]) if (!ctx.items.all.includes(item)) forget(item);
162	    },
163	  };
164	};
165	
166	export default create;
