5	/**
6	 * D4 肩越しに後ろへ放る。持っている物を肩越しに頭の後ろへ持っていって離すと、見えないゴミ箱に入って消える。
7	 */
8	
9	/** 頭の中心から見て、これ以上後ろ (頭の水平な前方向と逆) にあること (m)。頭の半径が約 0.1 m なので、耳の後ろまで回したら後ろとみなす。 */
10	export const BEHIND_MIN = 0.12;
11	/** 頭からの距離の上限 (m)。肩越しに後ろへ回した手が届く範囲 (腕の長さ約 0.6～0.7 m) より少し広めに取る。遠くへ投げた物は対象にしない。 */
12	export const REACH_MAX = 0.75;
13	/** 高さの下限 (頭より何 m 低いまで許すか)。目から肩までが約 0.25～0.3 m なので、肩の高さ以上を「肩越し」とする。腰の後ろでの誤爆を避ける。 */
14	export const SHOULDER_DROP = 0.3;
15	/** 前方向の水平成分がこれより小さい (真上・真下を向いている) ときは、後ろの向きが決められないので対象にしない。 */
16	const MIN_FORWARD_HORIZONTAL = 0.1;
17	
18	/**
19	 * 「普通に後ろへ投げたいボール」を消さないための条件。
20	 * 投げるときの手は、後ろの領域を一瞬で通り抜ける。消したいときは、その領域で手を止めて、
21	 * 振動で知らせを受けてから離す。そこで、領域に入ってから離すまでに DWELL_SEC 以上かかり、
22	 * 離す瞬間の手の速さが RELEASE_SPEED_MAX 以下であることを求める。
23	 * 後ろへ向けた緩い投げ (下手) は、手が領域を通る時間が短く速いので、この 2 つで消えない。
24	 */
25	/** 領域に入ってから離すまでの最短時間 (秒)。振動の知らせ 1 回分より長く、待ち続けても苦にならない長さ。 */
26	export const DWELL_SEC = 0.35;
27	/** 離す瞬間の手の速さの上限 (m/s)。人が物をそっと置くときはおよそ 0.5 m/s 以下、投げは 2 m/s 以上になる。 */
28	export const RELEASE_SPEED_MAX = 1.2;
29	
30	/** 領域の中にいる間、知らせの振動を繰り返す間隔 (秒) と、その強さ・長さ */
31	const HINT_INTERVAL = 0.25;
32	const HINT_INTENSITY = 0.12;
33	const HINT_MS = 40;
34	/** 領域に入った瞬間と、消える瞬間の振動 */
35	const ENTER_INTENSITY = 0.3;
36	const ENTER_MS = 60;
37	const DELETE_INTENSITY = 1;
38	const DELETE_MS = 120;
