45	 * 頭の水平な前方向に対する後ろ向きの距離・頭からの距離・高さで判定する。
46	 */
47	export function isOverShoulder(
48	  headPosition: THREE.Vector3,
49	  headQuaternion: THREE.Quaternion,
50	  position: THREE.Vector3,
51	): boolean {
52	  _forward.set(0, 0, -1).applyQuaternion(headQuaternion);
53	  _forward.y = 0;
54	  const length = _forward.length();
55	  if (length < MIN_FORWARD_HORIZONTAL) return false;
56	  _forward.divideScalar(length);
57	  _offset.copy(position).sub(headPosition);
58	  const behind = -(_offset.x * _forward.x + _offset.z * _forward.z);
