115	        const state = zone.get(hand);
116	        if (!inZone) {
117	          zone.delete(hand);
118	          continue;
119	        }
120	        if (!state) {
121	          zone.set(hand, { since: now, lastHint: now });
122	          hand.pulse(ENTER_INTENSITY, ENTER_MS);
123	        } else if (now - state.since >= DWELL_SEC && now - state.lastHint >= HINT_INTERVAL) {
124	          // 「ここで離すと消える」状態になってから、弱い振動を繰り返す。
125	          state.lastHint = now;
126	          hand.pulse(HINT_INTENSITY, HINT_MS);
127	        }
128	      }
129	    },
130	  };
131	};
