1	// D2 写真を破る: 両手で持った写真を、片手は手前・もう片手は奥へ素早く逆向きに動かすと、左右 2 枚に破れて落ちて消える。
2	import * as THREE from 'three';
3	import type { FrameContext } from '../../app';
4	import type { HandState } from '../../input';
5	import type { Item } from '../../items';
6	import type { InteractionFactory } from '../types';
7	
8	/** 両手を結ぶ線に垂直な、互いに逆向きの相対速度がこれ以上 (m/s)。両手で拡大縮小・回転する普通の動きは 0.5 m/s 未満に収まるので、その倍以上の素早さを要求する。 */
9	export const TEAR_RELATIVE_SPEED = 1.2;
10	/** 破るとき、各手がそれぞれ出していなければならない垂直方向の速さ (m/s)。片手だけを振っても (もう片手がほぼ止まったままでも) 破れない。 */
11	export const TEAR_EACH_HAND_SPEED = 0.35;
12	/** 線に沿った相対速度 (拡大縮小) が、垂直な相対速度のこの割合を超えたら、引き伸ばしと見なして破らない。 */
13	export const TEAR_MAX_ALONG_RATIO = 0.5;
14	/** 上の条件を満たし続ける時間 (秒)。手の速度は 1 フレームだけ跳ねることがあるので、少し続いたときだけ破る。 */
15	export const TEAR_SUSTAIN = 0.08;
16	/** 破れてから消えるまでの時間 (秒) */
17	const FALL_DURATION = 0.9;
18	/** 破片が左右へ離れる速さ (m/s、写真の大きさに対する倍率前) */
19	const SPREAD_SPEED = 0.18;
20	/** 破片が落ちる加速度 (m/s^2)。実際の重力より弱めにして、ひらひら落ちる見た目にする */
21	const FALL_GRAVITY = 3;
22	/** 破片が回る速さ (rad/s)。左右で逆向きに回す */
23	const SPIN_SPEED = 1.4;
24	
25	const _axis = new THREE.Vector3();
26	const _vl = new THREE.Vector3();
27	const _vr = new THREE.Vector3();
28	const _rel = new THREE.Vector3();
29	const _dir = new THREE.Vector3();
30	
31	/**
32	 * 両手の位置と速度から、破る動きか判定する (純粋な計算)。
33	 * 両手を結ぶ線に垂直な成分だけを取り出し、互いに逆向きで十分速く、線に沿った動きより支配的かを見る。
34	 */
35	export function isTearingMotion(
36	  leftPos: THREE.Vector3,
37	  rightPos: THREE.Vector3,
38	  leftVel: THREE.Vector3,
39	  rightVel: THREE.Vector3,
40	): boolean {
41	  _axis.subVectors(rightPos, leftPos);
42	  if (_axis.lengthSq() < 1e-6) return false;
43	  _axis.normalize();
44	  // 各手の速度から、線に沿った成分を引いて垂直成分にする
45	  _vl.copy(leftVel).addScaledVector(_axis, -leftVel.dot(_axis));
46	  _vr.copy(rightVel).addScaledVector(_axis, -rightVel.dot(_axis));
47	  _rel.subVectors(_vr, _vl);
48	  const perp = _rel.length();
49	  if (perp < TEAR_RELATIVE_SPEED) return false;
50	  const along = Math.abs(_dir.subVectors(rightVel, leftVel).dot(_axis));
51	  if (along > perp * TEAR_MAX_ALONG_RATIO) return false;
52	  _dir.copy(_rel).divideScalar(perp);
53	  // 相対運動の向きに対して、右手は正方向・左手は負方向へ、それぞれ十分動いている
54	  return _vr.dot(_dir) >= TEAR_EACH_HAND_SPEED && -_vl.dot(_dir) >= TEAR_EACH_HAND_SPEED;
55	}
56	
57	/** 写真の半分 (左: -1 / 右: +1) の板。写真の中心を原点とするローカル座標のまま、UV もテクスチャの半分に合わせる。 */
58	function halfPlane(width: number, height: number, side: -1 | 1, uvStart: number, uvEnd: number): THREE.PlaneGeometry {
59	  const geometry = new THREE.PlaneGeometry(width / 2, height);
60	  geometry.translate((side * width) / 4, 0, 0);
61	  const uv = geometry.getAttribute('uv');
62	  for (let i = 0; i < uv.count; i++) {
63	    uv.setX(i, uvStart + uv.getX(i) * (uvEnd - uvStart));
64	  }
65	  return geometry;
66	}
67	
68	interface Fragment {
69	  group: THREE.Group;
70	  side: -1 | 1;
71	  age: number;
72	  /** 下向きの速さ (m/s、写真のローカルではなくワールド) */
73	  fall: number;
74	  materials: THREE.MeshBasicMaterial[];
75	  textures: THREE.Texture[];
76	}
77	
78	const create: InteractionFactory = (ctx) => {
79	  const fragments: Fragment[] = [];
80	  let sustained = 0;
81	  let sustainedItem: Item | null = null;
82	
83	  const dispose = (fragment: Fragment): void => {
84	    ctx.app.scene.remove(fragment.group);
85	    for (const child of fragment.group.children) (child as THREE.Mesh).geometry.dispose();
86	    for (const material of fragment.materials) material.dispose();
87	    for (const texture of fragment.textures) texture.dispose();
88	  };
89	
90	  /** 写真と同じ位置・向き・大きさに、左右 2 枚の破片を出す。元の写真は呼び出し側が消す。 */
91	  const spawnFragments = (photo: Item): void => {
92	    const group = photo.object;
93	    const mount = group.children[0] as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | undefined;
94	    const picture = group.children[1] as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | undefined;
95	    const map = picture?.material.map;
96	    if (!mount || !picture) return;
97	    const { width, height } = picture.geometry.parameters;
98	    const mountWidth = mount.geometry.parameters.width;
99	    const mountHeight = mount.geometry.parameters.height;
100	    for (const side of [-1, 1] as const) {
101	      const fragment = new THREE.Group();
102	      const texture = map?.clone() ?? null;
103	      if (texture) texture.needsUpdate = true;
104	      const pictureMaterial = new THREE.MeshBasicMaterial({
105	        map: texture,
106	        side: THREE.DoubleSide,
107	        transparent: true,
108	      });
109	      const mountMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, transparent: true });
110	      const mountMesh = new THREE.Mesh(halfPlane(mountWidth, mountHeight, side, 0, 1), mountMaterial);
111	      mountMesh.position.z = mount.position.z;
112	      const pictureMesh = new THREE.Mesh(
113	        halfPlane(width, height, side, side < 0 ? 0 : 0.5, side < 0 ? 0.5 : 1),
114	        pictureMaterial,
115	      );
116	      fragment.add(mountMesh, pictureMesh);
117	      fragment.position.copy(group.position);
118	      fragment.quaternion.copy(group.quaternion);
119	      fragment.scale.copy(group.scale);
120	      ctx.app.scene.add(fragment);
121	      fragments.push({
122	        group: fragment,
123	        side,
124	        age: 0,
125	        fall: 0,
126	        materials: [pictureMaterial, mountMaterial],
127	        textures: texture ? [texture] : [],
128	      });
129	    }
130	  };
131	
132	  const tear = (photo: Item, hands: HandState[]): void => {
133	    const position = photo.object.position.clone();
134	    spawnFragments(photo);
135	    // 破る音は既存の音で代用する。紙を裂くような短い音を 2 つ、少しずらして鳴らす。
136	    ctx.audio.click(position);
137	    setTimeout(() => ctx.audio.click(position), 60);
138	    for (const hand of hands) hand.pulse(0.9, 80);
139	    ctx.items.remove(photo);
140	  };
141	
142	  return {
143	    id: 'D2',
144	    label: '破る',
145	    category: 'delete',
146	    disable() {
147	      for (const fragment of fragments) dispose(fragment);
148	      fragments.length = 0;
149	      sustained = 0;
150	      sustainedItem = null;
151	    },
152	    update(frame: FrameContext) {
153	      // 破片のアニメーション
154	      for (let i = fragments.length - 1; i >= 0; i--) {
155	        const fragment = fragments[i];
156	        fragment.age += frame.dt;
157	        const t = fragment.age / FALL_DURATION;
158	        if (t >= 1) {
159	          dispose(fragment);
160	          fragments.splice(i, 1);
161	          continue;
162	        }
163	        const scale = fragment.group.scale.x;
164	        // 写真のローカル x 方向 (写真の横向き) へ離れる
165	        _dir.set(fragment.side, 0, 0).applyQuaternion(fragment.group.quaternion);
166	        fragment.fall += FALL_GRAVITY * frame.dt;
167	        fragment.group.position
168	          .addScaledVector(_dir, SPREAD_SPEED * scale * frame.dt)
169	          .addScaledVector(_dir.set(0, -1, 0), fragment.fall * frame.dt);
170	        fragment.group.rotateZ(-fragment.side * SPIN_SPEED * frame.dt);
171	        const opacity = 1 - t * t;
172	        for (const material of fragment.materials) material.opacity = opacity;
173	      }
174	
175	      // 両手で持った写真が、破る動きをしているか
176	      const photo = ctx.items.all.find((item) => item.kind === 'photo' && ctx.items.holdersOf(item).length === 2);
177	      if (!photo) {
178	        sustained = 0;
179	        sustainedItem = null;
180	        return;
181	      }
182	      const hands = ctx.items.holdersOf(photo);
183	      const left = hands.find((hand) => hand.handedness === 'left');
184	      const right = hands.find((hand) => hand.handedness === 'right');
185	      if (!left || !right || !left.tracked || !right.tracked) {
186	        sustained = 0;
187	        return;
188	      }
189	      if (sustainedItem !== photo) {
190	        sustainedItem = photo;
191	        sustained = 0;
192	      }
193	      if (isTearingMotion(left.grabPosition, right.grabPosition, left.velocity, right.velocity)) {
194	        sustained += frame.dt;
195	        if (sustained >= TEAR_SUSTAIN) {
196	          sustained = 0;
197	          sustainedItem = null;
198	          tear(photo, hands);
199	        }
200	      } else {
201	        sustained = 0;
202	      }
203	    },
204	  };
205	};
206	
207	export default create;
